window.MORE=[
{id:"evo",t:"Evolution",c:"Science",i:"🦎",p:[["Natural selection","Evolution is change in the heritable traits of populations over generations. Charles Darwin and Alfred Russel Wallace independently proposed natural selection, and Darwin published On the Origin of Species in 1859."],["Evidence","Fossils, comparative anatomy and DNA all support common descent. Humans share roughly 98 to 99% of their DNA with chimpanzees."]],r:["dna","cell","evolution","naturalselection","sponges"]},
{id:"atom",t:"Atoms and the Periodic Table",c:"Science",i:"⚛️",p:[["The atom","Atoms consist of a nucleus of protons and neutrons surrounded by electrons. The number of protons defines the element."],["Periodic table","Dmitri Mendeleev published his periodic table in 1869 and predicted elements not yet discovered. Today it lists 118 confirmed elements."]],r:["light","elec","periodictable","chienshiungwu"]},
{id:"grav",t:"Gravity",c:"Science",i:"🍎",p:[["Theories","Newton described gravity as a force between masses in 1687. Einstein’s general relativity (1915) describes it as the curvature of spacetime."],["Effects","Gravity holds planets in orbit and produces ocean tides. On the Moon it is about one sixth as strong as on Earth."]],r:["solar","bh"]},
{id:"cell",t:"The Cell",c:"Science",i:"🔬",p:[["Basic unit","The cell is the basic unit of life. Robert Hooke coined the word in 1665 while examining cork under a microscope."],["Types","Bacteria have no nucleus, while plant and animal cells do. An adult human body contains tens of trillions of cells."]],r:["dna","evo","proteins","originoflife"]},
{id:"light",t:"Light and the Spectrum",c:"Science",i:"🌈",p:[["Speed","Light travels at about 299,792 km per second in a vacuum and behaves as both a wave and a stream of photons."],["Spectrum","Visible light is a narrow band of the electromagnetic spectrum, between infrared and ultraviolet. A prism splits white light into colors from red to violet."]],r:["atom","elec"]},
{id:"ww2",t:"World War II",c:"History",i:"🪖",p:[["Course","The war ran from 1939 to 1945 and involved most of the world’s nations, divided between the Allies and the Axis. It began with Germany’s invasion of Poland."],["Outcome","Germany surrendered in May 1945 and Japan in September 1945. The United Nations was founded in 1945, and the war is estimated to have killed 70 to 85 million people. Germany occupied most of Europe, and Japan much of East and Southeast Asia."]],r:["space","indrev"]},
{id:"renais",t:"The Renaissance",c:"History",i:"🎨",p:[["Rebirth","A cultural movement that began in Italy in the 14th century and spread across Europe, reviving interest in classical learning and art."],["Figures","Leonardo da Vinci, Michelangelo and Raphael produced masterpieces, while Gutenberg’s printing press spread new ideas quickly."]],r:["print","rome"]},
{id:"maya",t:"The Maya",c:"History",i:"🗿",p:[["Cities","The Maya civilization flourished in Mesoamerica, with its Classic period peaking between about 250 and 900 CE in cities such as Tikal and Palenque."],["Achievements","They developed a hieroglyphic writing system, advanced astronomy and an intricate calendar. Millions of Maya people live in Guatemala and Mexico today."]],r:["egypt","silk"]},
{id:"silk",t:"The Silk Road",c:"History",i:"🐪",p:[["Routes","A network of trade routes linking China with the Mediterranean from around the 2nd century BCE. Silk, spices and paper moved west, while goods and ideas moved in both directions."],["Impact","Religions, technologies and diseases also traveled along it. Sea routes gradually replaced much of the overland trade."]],r:["rome","sahara"]},
{id:"space",t:"The Space Race",c:"History",i:"🚀",p:[["Rivalry","A Cold War contest between the United States and the Soviet Union. The Soviets launched Sputnik 1 in 1957 and sent Yuri Gagarin into orbit in 1961."],["The Moon","Apollo 11 landed on the Moon on 20 July 1969, and Neil Armstrong was the first person to walk on its surface."]],r:["solar","flight"]},
{id:"everest",t:"Mount Everest",c:"Geography",i:"🏔️",p:[["Height","Earth’s highest mountain above sea level, at about 8,849 m, on the border of Nepal and Tibet. Tenzing Norgay and Edmund Hillary made the first confirmed ascent in 1953."],["Growth","It is still rising by a few millimeters a year as the Indian Plate pushes into Eurasia."]],r:["tect","antarc"]},
{id:"sahara",t:"The Sahara",c:"Geography",i:"🏜️",p:[["Size","The largest hot desert on Earth, covering about 9 million km² of North Africa, roughly the size of the United States."],["Terrain","Only a fraction is sand dunes. Most is rock and gravel, and several thousand years ago parts of it were green and well watered."]],r:["nile","tect"]},
{id:"pacific",t:"The Pacific Ocean",c:"Geography",i:"🌊",p:[["Scale","The largest and deepest ocean, covering about a third of the planet. The Mariana Trench holds its deepest point, nearly 11,000 m down."],["Ring of Fire","The belt of volcanoes and earthquake zones around its edge contains about 75% of the world’s active volcanoes."]],r:["ph","tect","palaucountry","marshallcountry"]},
{id:"nile",t:"The Nile",c:"Geography",i:"🛶",p:[["Length","At about 6,650 km it is traditionally counted as the longest river in the world, and its basin spans eleven countries before it reaches the Mediterranean."],["Role","Its annual floods made Egyptian agriculture possible. The Aswan High Dam, completed in 1970, now controls the flow."]],r:["egypt","sahara"]},
{id:"antarc",t:"Antarctica",c:"Geography",i:"🐧",p:[["Extremes","The southern continent is the coldest, driest and windiest on Earth. Its ice sheet holds about 70% of the world’s fresh water."],["Governance","No country owns it. The Antarctic Treaty of 1959 reserves it for peaceful scientific work."]],r:["pacific","everest","shackleton","krill"]},
{id:"comp",t:"The Computer",c:"Technology",i:"💻",p:[["Early machines","Charles Babbage designed the Analytical Engine in the 1830s, and ENIAC, completed in 1945, was among the first electronic general-purpose computers."],["Miniaturization","The transistor, invented in 1947, and the integrated circuit made computers small and cheap. Modern chips hold billions of transistors."]],r:["internet","elec"]},
{id:"print",t:"The Printing Press",c:"Technology",i:"📜",p:[["Invention","Johannes Gutenberg developed movable-type printing in Germany around 1450. His Bible was among the first major books printed in Europe."],["Impact","Books became cheaper and literacy rose, and ideas of the Renaissance, the Reformation and science spread quickly."]],r:["renais","internet","martinluther"]},
{id:"flight",t:"Flight",c:"Technology",i:"✈️",p:[["First flight","The Wright brothers made the first controlled, powered airplane flight on 17 December 1903 at Kitty Hawk, North Carolina."],["Jet age","Commercial jet service began in the 1950s, and Concorde carried passengers at more than twice the speed of sound from 1976 to 2003."]],r:["space","indrev"]},
{id:"renew",t:"Renewable Energy",c:"Technology",i:"🌞",p:[["Sources","Sunlight, wind, water and geothermal heat are replenished naturally. Solar panels turn light directly into electricity using the photovoltaic effect."],["Challenges","Wind and solar output varies with the weather, so grids need storage, flexible generation and strong transmission. Countries such as Iceland and Kenya also tap steady geothermal heat."]],r:["elec","photo"]},
{id:"gps",t:"GPS",c:"Technology",i:"📡",p:[["How it works","The Global Positioning System uses a constellation of satellites that broadcast time signals. A receiver needs signals from at least four of them to fix its position."],["Accuracy","Each satellite carries an atomic clock, and relativity corrections keep it accurate. Phones are typically accurate to within a few meters outdoors."]],r:["space","comp","satellites"]}];

